const readEnv = (name) => String($env[name] || '').trim();

let appUrl = readEnv('GEO_PRESENSI_URL');
const n8nApiKey = readEnv('N8N_API_KEY');
const gowaUrl = readEnv('GOWA_WEBHOOK_URL');
const adminPhone = readEnv('REMINDER_ADMIN_PHONE').replace(/[^0-9]/g, '');

while (appUrl.endsWith('/')) appUrl = appUrl.slice(0, -1);
if (appUrl.toLowerCase().endsWith('/api')) appUrl = appUrl.slice(0, -4);

if (!/^https:\/\//i.test(appUrl)) {
  throw new Error('GEO_PRESENSI_URL harus berupa URL HTTPS aplikasi, misalnya https://geo.griyaquran.web.id.');
}
if (!n8nApiKey) {
  throw new Error('N8N_API_KEY belum tersedia di environment n8n.');
}
if (!/^https:\/\//i.test(gowaUrl)) {
  throw new Error('GOWA_WEBHOOK_URL harus berupa URL HTTPS endpoint GOWA.');
}

const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Jakarta',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    hourCycle: 'h23'
  }).formatToParts(new Date()).map((part) => [part.type, part.value])
);
const hour = Number(parts.hour);
const reminderType = hour <= 8 ? 'first' : hour === 9 ? 'second' : 'final';
const reminderLabel = {
  first: 'Pengingat Presensi',
  second: 'Pengingat Presensi Kedua',
  final: 'Pengingat Presensi Terakhir'
}[reminderType];

return [{
  json: {
    appUrl,
    n8nApiKey,
    gowaUrl,
    adminPhone,
    tanggal: parts.year + '-' + parts.month + '-' + parts.day,
    reminderType,
    reminderLabel,
    executedAt: new Date().toISOString()
  }
}];

const response = $input.first().json;
const cfg = $items('Konfigurasi workflow')[0]?.json;

if (!cfg) throw new Error('Konfigurasi workflow tidak ditemukan.');
if (!response.success) {
  throw new Error(response.message || 'Aplikasi tidak dapat mengembalikan daftar guru.');
}

const payload = response.data || {};
const teachers = Array.isArray(payload.data) ? payload.data : [];
const normalizePhone = (raw) => {
  let phone = String(raw || '').trim().replace(/[^0-9+]/g, '');
  if (phone.startsWith('+')) phone = phone.slice(1);
  if (phone.startsWith('0')) phone = '62' + phone.slice(1);
  if (phone.startsWith('8')) phone = '62' + phone;
  return /^62\d{8,13}$/.test(phone) ? phone : '';
};

const messageFor = (name) => {
  const greeting = "Assalamu'alaikum Bapak/Ibu *" + name + "*,";
  const action = 'Silakan buka GeoPresensi dan lakukan presensi saat berada di area sekolah yang ditetapkan.\n👉 ' + cfg.appUrl;

  if (cfg.reminderType === 'second') {
    return ['🔔 *' + cfg.reminderLabel + '*', '', greeting, '', 'Presensi hari ini belum tercatat. Mohon luangkan waktu sebentar untuk melakukan presensi.', '', action, '', 'Jika berhalangan, gunakan pilihan Izin atau Sakit pada beranda.', '', '_Sistem GeoPresensi Griya Quran_'].join('\n');
  }
  if (cfg.reminderType === 'final') {
    return ['⚠️ *' + cfg.reminderLabel + '*', '', greeting, '', 'Kami mencatat presensi hari ini masih belum tercatat. Mohon segera melakukan presensi atau mengisi Izin/Sakit bila berhalangan.', '', action, '', 'Terima kasih. _Sistem GeoPresensi Griya Quran_'].join('\n');
  }
  return ['🔔 *' + cfg.reminderLabel + '*', '', greeting, '', 'Jangan lupa melakukan presensi hari ini melalui GeoPresensi.', '', action, '', "Semoga Allah Ta'ala mudahkan aktivitas Anda. _Sistem GeoPresensi Griya Quran_"].join('\n');
};

return teachers.flatMap((teacher) => {
  const phone = normalizePhone(teacher.noHP || teacher.no_hp);
  if (!phone) return [];
  const nama = String(teacher.nama || 'Guru').trim() || 'Guru';
  return [{
    json: {
      nama,
      phone,
      message: messageFor(nama),
      gowaUrl: cfg.gowaUrl,
      reminderType: cfg.reminderType,
      reminderLabel: cfg.reminderLabel,
      tanggal: payload.tanggal || cfg.tanggal
    }
  }];
});

const recipients = $items('Format penerima dan pesan').map((item) => item.json);
const cfg = $items('Konfigurasi workflow')[0]?.json;
if (!cfg) throw new Error('Konfigurasi workflow tidak ditemukan.');

const names = recipients.map((item, index) => String(index + 1) + '. ' + item.nama).join('\n') || '-';
const adminMessage = [
  '*Laporan Pengingat Presensi*',
  '',
  'Jenis: ' + cfg.reminderLabel,
  'Tanggal: ' + cfg.tanggal,
  'Pesan terkirim: ' + recipients.length + ' guru',
  '',
  names,
  '',
  '_Sistem GeoPresensi Griya Quran_'
].join('\n');

return [{
  json: {
    reminderType: cfg.reminderType,
    adminPhone: cfg.adminPhone,
    gowaUrl: cfg.gowaUrl,
    adminMessage
  }
}];
